from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused


def _bad(msg: str):
    return DataError("journal", msg)


def replay(entries: list[dict]):
    """Reads the journal with the two stacks (undo.md, section 2).

    Returns (done, undone, dropped): lists of operation lines.
    """
    done, undone, dropped = [], [], []
    for e in entries:
        op = e["op"]
        if op in journal.OPS:
            dropped.extend(undone)
            undone.clear()
            done.append(e)
        elif op == "undo":
            if not done or done[-1]["seq"] != e.get("target"):
                raise _bad(f"undo #{e['seq']} does not match the top of done")
            undone.append(done.pop())
        elif op == "redo":
            if not undone or undone[-1]["seq"] != e.get("target"):
                raise _bad(f"redo #{e['seq']} does not match the top of undone")
            done.append(undone.pop())
    return done, undone, dropped


def _changes_v2(e: dict) -> list[tuple[str, int]]:
    """(bin, quantity to set) pairs, in the order to apply them, to undo a format 2 line."""
    try:
        return [(normalize(x["bin"]), x["before"]) for x in reversed(e["effects"])]
    except (KeyError, TypeError):
        raise _bad(f"#{e['seq']}: bad effects") from None


def _units(ctx, e: dict) -> int:
    qty = e["qty"]
    if e.get("uom") == "pk":
        item = ctx.items.get(e["sku"])
        if item is None:
            raise Refused("unknown-sku", f"no item {e['sku']}")
        return qty * item.pack_size
    return qty


def _deltas_v1(ctx, e: dict) -> list[tuple[str, int]]:
    """(bin, signed change to apply) pairs, in the order to apply them, to undo a format 1 line."""
    try:
        op = e["op"]
        if op == "receive":
            return [(normalize(e["bin"]), -_units(ctx, e))]
        if op == "issue":
            return [(normalize(b), q) for b, q in reversed(e["picks"])]
        if op == "move":
            return [(normalize(e["to"]), -e["qty"]), (normalize(e["from"]), e["qty"])]
    except (KeyError, TypeError, ValueError):
        raise _bad(f"#{e['seq']}: bad line") from None
    raise _bad(f"#{e['seq']}: cannot undo")


def _apply(ctx, store, sku: str, steps, relative: bool) -> list[dict]:
    """Sets bins on store; returns the effects. Nothing is refused for a retired bin."""
    for code, _ in steps:
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")
    effects = []
    for code, value in steps:
        before = store.qty(sku, code)
        after = before + value if relative else value
        store.restore(sku, code, after)
        effects.append({"bin": code, "before": before, "after": after})
    return effects


def run(ctx, kind: str, steps: int) -> list[str]:
    """Carries out `steps` undo or redo steps, all or nothing. Returns the output lines."""
    done, undone, _ = replay(ctx.entries)
    entries = list(ctx.entries)
    store = ctx.store.copy()
    new, lines = [], []
    for _ in range(steps):
        if kind == "undo":
            if not done:
                raise Refused("nothing-to-undo", "nothing to undo")
            target = done[-1]
            if target["op"] == "fix":
                raise Refused("barrier", "the latest operation is a fix")
            sku = target.get("sku", "")
            if target.get("v") == 2:
                effects = _apply(ctx, store, sku, _changes_v2(target), False)
            else:
                if target["op"] == "count":
                    raise Refused("irreversible", "a format 1 count cannot be undone")
                effects = _apply(ctx, store, sku, _deltas_v1(ctx, target), True)
            undone.append(done.pop())
        else:
            if not undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            target = undone[-1]
            sku = target.get("sku", "")
            prior = next((e for e in reversed(entries)
                          if e["op"] == "undo" and e.get("target") == target["seq"]), None)
            if prior is None:
                raise _bad(f"no undo line for #{target['seq']}")
            effects = _apply(ctx, store, sku, _changes_v2(prior), False)
            done.append(undone.pop())
        line = journal.entry(journal.next_seq(entries), kind, ctx.by, sku,
                             target=target["seq"], effects=effects)
        entries.append(line)
        new.append(line)
        lines.append(f"#{line['seq']} {kind} {sku} (#{target['seq']} {target['op']})")
        lines.extend(f"  {x['bin']} {x['before']} -> {x['after']}" for x in effects)
    ctx.commit(store, new)
    return lines


def history(ctx, limit: int) -> list[str]:
    done, undone, dropped = replay(ctx.entries)
    status = {}
    for e in done:
        status[e["seq"]] = "barrier" if e["op"] == "fix" else "done"
    for e in undone:
        status[e["seq"]] = "undone"
    for e in dropped:
        status[e["seq"]] = "dropped"
    ops = [e for e in ctx.entries if e["op"] in journal.OPS]
    return [f"{e['seq']:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {status[e['seq']]}"
            for e in reversed(ops[-limit:])]
"}

